/* Payroll presentation aligned with the recorded screen and authorized demo.
   Earnings retain the existing completed-labour rule; no pay-policy migration. */
let payrollStaffFilter='all';
moduleGradients.payroll=[['#081d26','#0f3544'],['#0284c7','#0369a1'],['#10b981','#059669'],['#6366f1','#4f46e5'],['#ef4444','#dc2626']];
function payrollNormalizeText(value){return String(value??'').trim().replace(/\s+/g,' ').toLocaleLowerCase()}
function payrollIsPerJob(staff){return payrollNormalizeText(staff.salaryType).replace(/[-_]+/g,' ')==='per job'}
function payrollJobMatchesStaff(job,staff){const id=String(staff.id??'').trim(),name=payrollNormalizeText(staff.name),mechanic=String(job.mechanic??'').trim();return mechanic===id||payrollNormalizeText(mechanic)===name||payrollNormalizeText(job.mechanicName)===name}
function payrollJobsForStaff(staff){return db.jobs.filter(job=>payrollJobMatchesStaff(job,staff))}
function payrollJobIsPayable(job){return ['completed','delivered'].includes(payrollNormalizeText(job.status))}
function payrollExpenseMatchesStaff(expense,staff){const staffRef=String(expense.staff??'').trim();return staffRef===String(staff.id??'').trim()||payrollNormalizeText(staffRef)===payrollNormalizeText(staff.name)||payrollNormalizeText(expense.staffName)===payrollNormalizeText(staff.name)}
function payrollVisualRows(){return db.staff.filter(s=>payrollStaffFilter==='all'||payrollIsPerJob(s)).map(s=>{let assigned=payrollJobsForStaff(s).filter(j=>payrollNormalizeText(j.status)!=='cancelled'),completed=assigned.filter(payrollJobIsPayable),earned=payrollIsPerJob(s)?round(completed.reduce((n,j)=>n+billTotals(j).labour,0)*Number(s.salary)/100):0,paidAmount=db.expenses.filter(e=>payrollExpenseMatchesStaff(e,s)).reduce((n,e)=>n+Number(e.amount||0),0);return {...s,assigned:assigned.length,completed:completed.length,earned,paidAmount,balance:round(earned-paidAmount)}})}
payrollPage=function(){let rows=payrollVisualRows();return '<div class="notice payrollRule">Mechanic details and per-job rates sync from Staff Master. Commission uses completed/delivered job labour before tax and discounts; monthly and daily salary calculations are not included.</div>'+summary([['TOTAL MECHANICS',rows.length],['ASSIGNED JOBS',rows.reduce((n,s)=>n+s.assigned,0)+' Jobs'],['TOTAL SALARY GENERATED',money(rows.reduce((n,s)=>n+s.earned,0))],['TOTAL PAID (EXPENSES)',money(rows.reduce((n,s)=>n+s.paidAmount,0))],['TOTAL BALANCE DUE',money(rows.reduce((n,s)=>n+s.balance,0))]])+'<div class="toolbar payrollToolbar"><input id="search" class="search" value="'+esc(search)+'" placeholder="Search by mechanic name, ID, phone, address..." aria-label="Search payroll"><select id="payrollStaffFilter" aria-label="Payroll staff filter">'+opts([{value:'per-job',label:'Per Job Staff Only'},{value:'all',label:'All Mechanics & Staff'}],payrollStaffFilter)+'</select><span class="spacer"></span><button class="btn exportButton" data-action="export">'+icon('download')+' Export Excel</button><button class="btn secondary" id="refreshPayroll">'+icon('undo')+' Refresh</button></div><div class="payrollReviewTable">'+table(['Mechanic / Staff','Designation & Skills','Contact Details','Per Job Rate','Jobs Count','Total Salary (Earned)','Total Paid','Balance Due','Actions'],rows.filter(matches).map(s=>['<strong>'+esc(s.name)+'</strong><small>'+esc(s.id)+'</small>',badge(s.designation||'—')+'<small>'+esc(s.skills||'—')+'</small>',esc(s.mobile||'—')+'<small>'+esc(s.address||'')+'</small>',payrollIsPerJob(s)?esc(s.salary)+'% / Job':'— ('+esc(s.salaryType||'Not set')+')',s.assigned+' Jobs<small>'+s.completed+' completed / delivered</small>',money(s.earned),money(s.paidAmount),'<strong>'+money(s.balance)+'</strong>','<div class="rowactions"><button type="button" class="btn small secondary" data-extra-action="staff-jobs" data-key="staff" data-id="'+esc(s.id)+'">'+icon('eye')+' View All Works</button><button type="button" class="btn small success" data-extra-action="salary" data-key="staff" data-id="'+esc(s.id)+'" '+(payrollIsPerJob(s)?'':'disabled')+'>'+icon('wallet')+' Pay</button></div>']))+'</div>'};
const renderBeforePayrollVisual=render;
render=function(){renderBeforePayrollVisual();if(page!=='payroll')return;if($('#payrollStaffFilter'))$('#payrollStaffFilter').onchange=e=>{payrollStaffFilter=e.target.value;render()};if($('#refreshPayroll'))$('#refreshPayroll').onclick=()=>render()};
if(page==='payroll')render();
